<script>(()=>{const toggle=document.querySelector('[data-f406-menu-toggle]'),nav=document.querySelector('[data-f406-nav]');toggle?.addEventListener('click',()=>nav?.classList.toggle('is-open'));document.querySelector('[data-f406-search]')?.addEventListener('click',()=>document.querySelector('[data-f406-search-panel]')?.classList.toggle('is-open'));const reveals=[...document.querySelectorAll('[data-f406-reveal]')];if('IntersectionObserver'in window&&!matchMedia('(prefers-reduced-motion: reduce)').matches){const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');observer.unobserve(entry.target)}}),{threshold:.1,rootMargin:'0px 0px -35px'});reveals.forEach(item=>observer.observe(item))}else reveals.forEach(item=>item.classList.add('is-visible'));document.querySelectorAll('[data-f406-slider]').forEach(slider=>{const slides=[...slider.querySelectorAll('[data-f406-slide]')];if(slides.length<2)return;let active=0,timer;const show=next=>{active=(next+slides.length)%slides.length;slides.forEach((slide,index)=>slide.classList.toggle('is-active',index===active))};const play=()=>{clearInterval(timer);timer=setInterval(()=>show(active+1),5200)};slider.querySelector('[data-f406-prev]')?.addEventListener('click',()=>{show(active-1);play()});slider.querySelector('[data-f406-next]')?.addEventListener('click',()=>{show(active+1);play()});play()})})();</script>
